/**
 * MCP bindings.
 *
 * The agent reads from Sanity via the Context MCP server (hosted, read-only).
 * The agent writes via direct Sanity HTTP API calls (Context MCP cannot write).
 *
 * Day-6 work: wire `@ai-sdk/mcp` to the Sanity Context endpoint.
 *
 * Both endpoints are wired in:
 *   - GROQ-mode endpoint (live dataset, schema-aware structured queries)
 *   - KB-mode endpoint (compiled Knowledge Base index, cited + contradiction-checked)
 *
 * Note: ONE endpoint serves ONE mode. An endpoint with both dataset and
 * knowledge-base sources ignores the KB sources, so both live as separate
 * endpoints in the Sanity dashboard (SANITY_CONTEXT_MCP_URL for GROQ-mode,
 * SANITY_CONTEXT_KB_MCP_URL for KB-mode) and their tools are merged for the
 * planner/query agents — see readEnvMcpConfigs / mergeClientTools below.
 */

import { createMCPClient } from '@ai-sdk/mcp'

export interface SanityMCPConfig {
  endpointUrl: string
  token: string
}

/** A config plus a short label used to disambiguate tool names that collide
 *  across endpoints (both GROQ-mode and KB-mode expose `initial_context`). */
export interface NamedMcpConfig extends SanityMCPConfig {
  label: string
}

export async function createSanityContextClient(config: SanityMCPConfig) {
  return createMCPClient({
    transport: {
      type: 'http',
      url: config.endpointUrl,
      headers: {
        Authorization: `Bearer ${config.token}`,
      },
    },
  })
}

type SanityMcpClient = Awaited<ReturnType<typeof createSanityContextClient>>

export interface NamedMcpClient {
  label: string
  client: SanityMcpClient
}

/** Single-endpoint config, kept for callers that only ever talk GROQ-mode. */
export function readEnvMcpConfig(): SanityMCPConfig {
  const url = process.env.SANITY_CONTEXT_MCP_URL
  const token = process.env.SANITY_CONTEXT_TOKEN
  if (!url || !token) {
    throw new Error(
      'SANITY_CONTEXT_MCP_URL and SANITY_CONTEXT_TOKEN must be set. See .env.example.',
    )
  }
  return { endpointUrl: url, token }
}

/**
 * Reads every configured Context MCP endpoint. GROQ-mode
 * (SANITY_CONTEXT_MCP_URL) is required; KB-mode (SANITY_CONTEXT_KB_MCP_URL)
 * is optional and, when present, is wired in alongside it. Context Viewer is
 * an org-level grant, so the GROQ token authorizes the KB endpoint too unless
 * SANITY_CONTEXT_KB_TOKEN overrides it.
 */
export function readEnvMcpConfigs(): NamedMcpConfig[] {
  const groq = readEnvMcpConfig()
  const configs: NamedMcpConfig[] = [{ ...groq, label: 'groq' }]

  const kbUrl = process.env.SANITY_CONTEXT_KB_MCP_URL
  if (kbUrl) {
    const kbToken = process.env.SANITY_CONTEXT_KB_TOKEN || groq.token
    configs.push({ endpointUrl: kbUrl, token: kbToken, label: 'kb' })
  }

  return configs
}

export async function createSanityContextClients(
  configs: NamedMcpConfig[],
): Promise<NamedMcpClient[]> {
  return Promise.all(
    configs.map(async (config) => ({
      label: config.label,
      client: await createSanityContextClient(config),
    })),
  )
}

export async function closeAll(clients: NamedMcpClient[]): Promise<void> {
  await Promise.all(clients.map(({ client }) => client.close()))
}

/**
 * Merges tool sets from every connected endpoint into one object suitable for
 * `generateText({ tools })`. GROQ-mode and KB-mode both expose `initial_context`
 * under the same name — the first registration wins the bare name (GROQ is
 * always first from readEnvMcpConfigs) and later collisions are exposed under
 * a `<label>_<name>` alias so both stay reachable rather than one silently
 * shadowing the other.
 */
export async function mergeClientTools(
  clients: NamedMcpClient[],
): Promise<Record<string, unknown>> {
  const merged: Record<string, unknown> = {}
  for (const { label, client } of clients) {
    const tools = (await client.tools()) as Record<string, unknown>
    for (const [name, tool] of Object.entries(tools)) {
      const key = name in merged ? `${label}_${name}` : name
      merged[key] = tool
    }
  }
  return merged
}

/**
 * Planner — the only Quicksilver agent.
 *
 * Connects to Sanity Context MCP, exposes the structured content as tools to
 * the planner model, and returns a structured plan for the kernel to authorize.
 *
 * Day 6: connectivity verified end-to-end.
 * Day 7: returns candidate actions in ProposedAction shape.
 * Day 9: candidate actions become a full decision artifact via the kernel.
 */

import { generateText, Output, stepCountIs } from 'ai'
import { z } from 'zod'

import { PLANNER_SYSTEM_PROMPT } from './prompts.ts'
import { isLlmConfigured, modelForRole } from './models.ts'
import {
  closeAll,
  createSanityContextClients,
  mergeClientTools,
  readEnvMcpConfigs,
} from './mcp.ts'
import type { ProposedAction } from '@quicksilver/kernel'

export interface PlannerInput {
  objective: string
  /** Optional pre-loaded context to skip MCP round-trips (used for tests). */
  context?: Record<string, unknown>
}

const ProposedActionSchema = z.object({
  description: z.string(),
  actorId: z.string(),
  capabilityId: z.string(),
  applicablePolicyIds: z.array(z.string()),
  evidenceIds: z.array(z.string()),
  // Required (not `.default(0)`): strict JSON-schema output needs every property in `required`.
  financialExposure: z.number().describe('Estimated financial exposure in USD; use 0 if none'),
  reversible: z.boolean(),
  operationalImpact: z.number().int().min(0).max(5),
  uncertainty: z.number().int().min(0).max(5),
})

export const PlanOutputSchema = z.object({
  decomposition: z.object({
    objective: z.string(),
    constraints: z.array(z.string()),
    successMetrics: z.array(z.string()),
    requiredCapabilities: z.array(z.string()),
    candidateWorkstreams: z.array(z.string()),
  }),
  candidateActions: z.array(ProposedActionSchema).min(1),
  reasoning: z.string(),
})

export type PlannerOutput = z.infer<typeof PlanOutputSchema>

/** Re-exported so callers can gate on it without importing models directly. */
export { isLlmConfigured }

/**
 * Max model steps (one step = one model call, plus any tool calls it makes).
 * `generateText` defaults to a single step, which ends the run right after the
 * first tool call — before the model can emit its structured plan.
 */
const PLANNER_MAX_STEPS = 15

export async function planObjective(input: PlannerInput): Promise<PlannerOutput> {
  if (!isLlmConfigured()) {
    throw new Error(
      'No LLM configured. Set AZURE_API_KEY + AZURE_RESOURCE_NAME (or OPENAI_API_KEY / ANTHROPIC_API_KEY / GOOGLE_GENERATIVE_AI_API_KEY) in .env.',
    )
  }

  const mcpConfigs = readEnvMcpConfigs()
  const clients = await createSanityContextClients(mcpConfigs)

  try {
    const tools = await mergeClientTools(clients)

    // Day 8: agentic loop with structured output. The model uses MCP tools
    // to discover entities/capabilities/policies/evidence, then emits a plan
    // matching the ProposedAction shape — which the kernel can authorize
    // directly without further transformation.
    const result = await generateText({
      model: modelForRole('planner'),
      system: PLANNER_SYSTEM_PROMPT,
      prompt: `Decompose this company objective and propose candidate actions:

"""${input.objective}"""

Step 1: Use the available tools (groq_query, schema_explorer, knowledge_base_read) to discover:
  - Which entities have which capabilities
  - Which policies apply to the actions you're considering
  - Which evidence (reports, analyses, vendor bulletins) is relevant

Step 2: Emit a structured plan. The candidateActions array MUST contain at least one action. Each action must reference entities and capabilities by their Sanity document IDs (e.g., "entity-engineering-agent", "cap-process-param"). Do NOT invent IDs — only use IDs you actually retrieved.

The kernel will compute risk and authorization from your candidate actions. Be specific about which policies apply.`,
      tools: tools as unknown as Parameters<typeof generateText>[0]['tools'],
      experimental_output: Output.object({ schema: PlanOutputSchema }),
      stopWhen: stepCountIs(PLANNER_MAX_STEPS),
      maxRetries: 2,
    } as Parameters<typeof generateText>[0])

    const parsed = (result as unknown as { experimental_output?: PlannerOutput }).experimental_output
    if (!parsed || parsed.candidateActions.length === 0) {
      throw new Error('Planner produced no candidate actions.')
    }
    return parsed
  } finally {
    await closeAll(clients)
  }
}

/**
 * Day 7 — simple query agent.
 *
 * Structured Q&A over the company model. Uses AI SDK's `generateObject`
 * with a Zod schema so the response shape is enforced (no prose, no CoT
 * leaking to callers).
 *
 * Example:
 *   "Who can perform process parameter modification?"
 *   → {
 *       question: "...",
 *       entities: [{ id: "entity-engineering-agent", name: "Engineering Agent", ... }, ...],
 *       supportingContext: ["Capability 'Process Parameter Modification' authorizes 3 entities…"],
 *       confidence: 0.95,
 *     }
 */

import { generateText, Output, stepCountIs } from 'ai'
import { z } from 'zod'

import { QUERY_SYSTEM_PROMPT } from './prompts.ts'
import { isLlmConfigured, modelForRole } from './models.ts'
import {
  closeAll,
  createSanityContextClients,
  mergeClientTools,
  readEnvMcpConfigs,
} from './mcp.ts'

export const QueryResultSchema = z.object({
  question: z.string(),
  entities: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      entityType: z.string(),
      role: z.string().optional(),
      reasoning: z.string(),
    }),
  ),
  capabilities: z
    .array(
      z.object({
        id: z.string(),
        name: z.string(),
        riskLevel: z.number().int().min(0).max(5),
      }),
    )
    .default([]),
  policies: z
    .array(
      z.object({
        id: z.string(),
        name: z.string(),
        scope: z.string(),
      }),
    )
    .default([]),
  supportingContext: z.array(z.string()),
  confidence: z.number().min(0).max(1),
})

export type QueryResult = z.infer<typeof QueryResultSchema>

export async function queryCompany(question: string): Promise<QueryResult> {
  if (!isLlmConfigured()) {
    throw new Error(
      'No LLM configured. Set AZURE_API_KEY + AZURE_RESOURCE_NAME (or OPENAI_API_KEY / ANTHROPIC_API_KEY / GOOGLE_GENERATIVE_AI_API_KEY) in .env.',
    )
  }

  const mcpConfigs = readEnvMcpConfigs()
  const clients = await createSanityContextClients(mcpConfigs)

  try {
    const tools = await mergeClientTools(clients)

    // Structured output via `experimental_output` (still supported in AI SDK 6).
    // The tool-call loop runs first — `stopWhen` is required, because the default
    // is a single step, which ends the run right after the first tool call —
    // then the model emits a final JSON message matching the Zod schema.
    const result = await generateText({
      model: modelForRole('planner'),
      system: QUERY_SYSTEM_PROMPT,
      prompt: `Question: ${question}`,
      tools: tools as unknown as Parameters<typeof generateText>[0]['tools'],
      experimental_output: Output.object({
        schema: QueryResultSchema,
      }),
      stopWhen: stepCountIs(12),
      maxRetries: 2,
    } as Parameters<typeof generateText>[0])

    const parsed = (result as unknown as { experimental_output?: QueryResult }).experimental_output
    if (!parsed) {
      throw new Error('Model did not return structured output.')
    }
    return parsed
  } finally {
    await closeAll(clients)
  }
}

