      )
      const text = JSON.stringify(result)
      console.log(`Returned ${text.length} bytes`)
      console.log(text.slice(0, 1200) + (text.length > 1200 ? '…' : ''))
    }
  } catch (err) {
    console.log(`✗ knowledge_base_read failed: ${(err as Error).message}`)
  }
  console.log()
}

